import { createElement, dynamicAttr, updateDynamicAttributeOnChildren } from '../shared/dom-manipulation';
import { NeonWidgetSlotted } from '../shared/neon-widget-slotted';
import { stringHasCharacters } from '../shared/string-utils';
import './neon-avatar-button.scss';
/** Overall, this component code is simple. It's a button that wraps around
 *  the neon avatar component to give it click functionality.
 *  The only thing we should note is that if the Avatar inputs or code change,
 *  then we need to make sure this Avatar Button component does not break as well
 */
export class NeonAvatarButton extends NeonWidgetSlotted {
    static get observedAttributes() {
        return ['id', 'data-aria-label'];
    }
    static get requiredSlots() {
        return [
            { slot: 'avatar', tag: 'neon-2_20_1-avatar' }
        ];
    }
    constructor() {
        super();
        this.widgetTag = 'neon-avatar-button';
        super.isIdRequired = true;
    }
    attributeChanged(attrName, oldVal, newVal) {
        super.attributeChanged(attrName, oldVal, newVal);
        switch (attrName) {
            case 'id':
                updateDynamicAttributeOnChildren(this, 'id');
                break;
            case 'data-aria-label':
                updateDynamicAttributeOnChildren(this, 'aria-label');
                break;
            default:
                break;
        }
    }
    renderAvatarButton() {
        return createElement('button', {
            attrs: {
                id: dynamicAttr(() => {
                    return 'neon-avatar-button-' + this.getAttribute('id');
                }),
                'aria-label': dynamicAttr(() => {
                    return this.getAttribute('data-aria-label');
                })
            }
        }, this.getSlot('avatar'));
    }
    validateInputs() {
        super.validateInputs();
        if (!stringHasCharacters(this.getAttribute('data-aria-label'))) {
            console.error('You must set the data-aria-label on the neon-avatar-button with id: ' + this.getAttribute('id'), this);
        }
        const avatarElement = this.querySelector('[data-slot="avatar"]');
        if (avatarElement != null) {
            if (avatarElement.tagName.toLowerCase() !== 'neon-2_20_1-avatar') {
                console.error('The avatar slot must contain a neon-avatar');
            }
            if (avatarElement.getAttribute('data-avatar-size-mobile') == null && avatarElement.getAttribute('data-avatar-size') === 'extra-small' ||
                avatarElement.getAttribute('data-avatar-size-mobile') === 'extra-small') {
                console.error('The avatar cannot have size x-small on mobile. Define the size using data-avatar-size-mobile');
            }
        }
    }
    render() {
        return this.renderAvatarButton();
    }
}
